{"command":"python3 << 'PYEOF'
import re

with open('reports/pipeline_report.md', 'r') as f:
    content = f.read()

sections = ['Overview', 'Input data', 'Methods', 'Generated outputs', 'Main results', 'Limitations', 'Reproducibility']

for i, section in enumerate(sections):
    # Find section header and next section
    if i < len(sections) - 1:
        next_section = sections[i + 1]
        pattern = rf'#{section}\n(.*?)(?=#{next_section})'
    else:
        # Last section - find until end
        pattern = rf'#{section}\n(.*?)$'

    match = re.search(pattern, content, re.DOTALL)
    if match:
        text = match.group(1).strip()
        chars = len(text)
        print(f'{section}: {chars} characters')
        if chars < 80:
            print(f'  WARNING: Less than 80 characters!')
    else:
        print(f'{section}: NOT FOUND')
PYEOF"}

